@CrossOrigin
@RestController
@RequestMapping("/PaymentQuery")
public class PaymentQueryRestController extends BaseSpringRestController {
	
	public PaymentQueryRestController( PaymentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Payment using a UUID
     * @param		UUID paymentId
     * @return		Payment
     */    
    @GetMapping("/load")
    public Payment load( @RequestParam(required=true) UUID paymentId ) {
    	Payment entity = null;

    	try {  
    		entity = service.getPayment( new PaymentFetchOneSummary( paymentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Payment using Id " + paymentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Payment business objects
     * @return		Set<Payment>
     */
    @GetMapping("/")
    public List<Payment> loadAll() {                
    	List<Payment> paymentList = null;
        
    	try {
            // load the Payment
            paymentList = service.getAllPayment();
            
            if ( paymentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Payments" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Payments ", exc );
        	return null;
        }

        return paymentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Payment payment = null;
    protected PaymentService service = null;
    private static final Logger LOGGER = Logger.getLogger(PaymentQueryRestController.class.getName());
    
}
